109	/**
110	 * findUser searches for an auth user in a project.
111	 * @param project project identifier.
112	 * @param email the users email to lookup.
113	 * @param phone the users phone number to lookup.
114	 * @param uid the users id to lookup.
115	 * @return an array of user info
116	 */
117	export async function findUser(
118	  project: string,
119	  email?: string,
120	  phone?: string,
121	  uid?: string,
122	): Promise<UserInfo> {
123	  const expression: { email?: string; phoneNumber?: string; userId?: string } = {
124	    email,
125	    phoneNumber: phone,
126	    userId: uid,
127	  };
128	  const res = await apiClient.post<
129	    {
130	      limit: string;
131	      expression: { email?: string; phoneNumber?: string; userId?: string }[];
132	    },
133	    {
134	      recordsCount: string;
135	      userInfo: UserInfo[];
136	    }
137	  >(`/v1/projects/${project}/accounts:query`, {
138	    expression: [expression],
139	    limit: "1",
140	  });
141	  if (!res.body.userInfo?.length) {
142	    throw new Error("No users found");
143	  }
144	  const modifiedUserInfo = res.body.userInfo.map((ui) => {
145	    ui.uid = ui.localId;
146	    delete ui.localId;
147	    return ui;
148	  });
149	  return modifiedUserInfo[0];
150	}
