import { aiLogicOrigin } from "../api";
import { getErrStatus } from "../error";
import * as backend from "../deploy/functions/backend";
import * as events from "../functions/events";

const API_VERSION = "v1beta";

/** An HTTP client for communicating with the AI Logic API. */
export const client = new Client({ urlPrefix: aiLogicOrigin(), apiVersion: API_VERSION });

/** An endpoint with an AI Logic blocking trigger. */
export type Endpoint = backend.Endpoint & backend.BlockingTriggered;

interface Trigger {
  cloudFunction: {
    id: string;
    locationId: string;
  };
}

/**
 * Maps an AI Logic blocking event type to the trigger id used in API calls.
 */
function triggerId(endpoint: backend.Endpoint & backend.BlockingTriggered): string {
  switch (endpoint.blockingTrigger.eventType) {
    case events.v2.AI_LOGIC_BEFORE_GENERATE_CONTENT:
      return "before-generate-content";
    case events.v2.AI_LOGIC_AFTER_GENERATE_CONTENT:
      return "after-generate-content";
    default:
      throw new Error(
        `Unexpected AI Logic blocking event type ${endpoint.blockingTrigger.eventType}`,
      );
  }
}

/**
 * Returns the location id used in the AI Logic API path. Global triggers (no
 * regionalWebhook option) use "global"; regional triggers use their region.
 */
function locationId(endpoint: backend.Endpoint & backend.BlockingTriggered): string {
  return endpoint.blockingTrigger.options?.regionalWebhook ? endpoint.region : "global";
}

function triggerBody(endpoint: backend.Endpoint & backend.BlockingTriggered): Trigger {
  return {
    cloudFunction: {
      id: endpoint.id,
      locationId: endpoint.region,
    },
  };
}

/**
 * Creates a new AI Logic blocking trigger via POST. If the POST fails with an
 * HTTP 409 (conflict), falls back to a PATCH to update the existing trigger.
 * For any other POST failure, the error is re-thrown without calling PATCH.
 * @param endpoint the AI Logic blocking endpoint
 */
export async function upsertBlockingFunction(
  endpoint: backend.Endpoint & backend.BlockingTriggered,
): Promise<void> {
  const location = locationId(endpoint);
  const trigger = triggerId(endpoint);
  const body = triggerBody(endpoint);
  try {
    await client.post<Trigger, unknown>(
      `projects/${endpoint.project}/locations/${location}/triggers`,
      body,
      {
        queryParams: { triggerId: trigger, validateOnly: "false" },
      },
    );
  } catch (err: unknown) {
    if (getErrStatus(err) !== 409) {
      throw err;
    }
    await client.patch<Trigger, unknown>(
      `projects/${endpoint.project}/locations/${location}/triggers/${trigger}`,
      body,
      {
        queryParams: { allowMissing: "false", validateOnly: "false" },
      },
    );
  }
}

/**
 * Deletes an AI Logic blocking trigger. Uses allowMissing: "true" so that
 * deletion is idempotent.
 * @param endpoint the AI Logic blocking endpoint
 */
export async function deleteBlockingFunction(
  endpoint: backend.Endpoint & backend.BlockingTriggered,
): Promise<void> {
  const location = locationId(endpoint);
  const trigger = triggerId(endpoint);
  await client.delete<unknown>(
    `projects/${endpoint.project}/locations/${location}/triggers/${trigger}`,
    {
      queryParams: { allowMissing: "true", validateOnly: "false" },
    },
  );
}
